const fs=require('fs'),path=require('path'),crypto=require('crypto');const root=process.env.OPENCODE_RECOVERY_ROOT||path.resolve(__dirname,'..');const esbuild=require(root+'/toolchain/node_modules/esbuild');const records=JSON.parse(fs.readFileSync(root+'/reports/baseline-manifest.json')).files;const bundled=new Set(JSON.parse(fs.readFileSync(root+'/reports/bundle-manifest.json')).bundles.map(x=>x.artifactPath));const standalone=records.filter(x=>!bundled.has(x.path)&&/^resources\/app\/(?:out\/|extensions\/)/.test(x.path)&&/\.(?:c|m)?js$/.test(x.path)&&!x.path.includes('/node_modules/')&&!x.path.includes('/runtime/git/')&&!/\/(?:test|tests)\//.test(x.path));const extraFile=root+'/recovered/workbench-assets.json';const extras=fs.existsSync(extraFile)?JSON.parse(fs.readFileSync(extraFile)):{static:[],scripts:[]};if(!Array.isArray(extras.scripts))throw Error('Invalid maintained scripts');for(const rel of extras.scripts){if(typeof rel!=='string'||rel.includes('..')||rel.includes('\\')||!/^resources\/app\/extensions\/opencode\/media\/task-workbench\/[a-z-]+\.js$/.test(rel))throw Error('Invalid maintained script path');if(!fs.existsSync(root+'/recovered/standalone/'+rel))throw Error('Maintained script source missing');if(!standalone.some(f=>f.path===rel))standalone.push({path:rel});}const output=[];const previous=fs.existsSync(root+'/reports/standalone-build.json')?JSON.parse(fs.readFileSync(root+'/reports/standalone-build.json')).files:[];
const pipelineHash=crypto.createHash('sha256').update(fs.readFileSync(__filename)).digest('hex');
(async()=>{for(const record of standalone){const source=root+'/recovered/standalone/'+record.path,dest=root+'/generated/source-build/'+record.path;fs.mkdirSync(path.dirname(source),{recursive:true});if(!fs.existsSync(source))fs.copyFileSync(root+'/baseline/'+record.path,source,fs.constants.COPYFILE_EXCL);const text=fs.readFileSync(source,'utf8');const sourceHash=crypto.createHash('sha256').update(text).digest('hex');const old=previous.find(x=>x.artifactPath===record.path);if(old?.compiler===esbuild.version&&old.pipelineHash===pipelineHash&&old.sourceHash===sourceHash&&fs.existsSync(dest)&&crypto.createHash('sha256').update(fs.readFileSync(dest)).digest('hex')===old.sha256){output.push({...old,unchanged:true});continue;}const r=await esbuild.transform(text,{loader:'js',target:'esnext',minify:false,legalComments:'inline',sourcemap:'external',sourcefile:source});fs.writeFileSync(dest,r.code+'\n//# sourceMappingURL='+path.basename(dest)+'.map\n');fs.writeFileSync(dest+'.map',r.map);output.push({compiler:esbuild.version,pipelineHash,source:source.slice(root.length+1),sourceHash,artifactPath:record.path,bytes:fs.statSync(dest).size,sha256:crypto.createHash('sha256').update(fs.readFileSync(dest)).digest('hex')});}
const productPath=root+'/generated/source-build/resources/app/product.json',product=JSON.parse(fs.readFileSync(productPath));const checksums=[];for(const key of Object.keys(product.checksums||{})){const file=root+'/generated/source-build/resources/app/out/'+key;const value=crypto.createHash('sha256').update(fs.readFileSync(file)).digest('base64').replace(/=+$/,'');checksums.push({path:key,changed:product.checksums[key]!==value});product.checksums[key]=value;}fs.writeFileSync(productPath,JSON.stringify(product,null,2)+'\n');const result={success:true,compiler:esbuild.version,files:output,productChecksums:checksums,integrityChecksRemainEnabled:true};fs.writeFileSync(root+'/reports/standalone-build.json',JSON.stringify(result,null,2));console.log('STANDALONE_BUILD '+JSON.stringify({success:true,files:output.length,changed:output.filter(x=>!x.unchanged).length,productChecksums:checksums,integrityChecksRemainEnabled:true}));})().catch(e=>{console.error(e);process.exitCode=1;});
